//! Bundled gameplay actors, loaded in the production host's separate phases.
use super::*;

mod source;

#[derive(Clone, Copy)]
pub(in crate::rust_engine) enum Phase {
    Combo,
    Transitions,
}

#[derive(Clone)]
struct Load {
    store: Shared,
    scene: u64,
    phase: Phase,
}

impl Actors {
    pub(in crate::rust_engine) fn load_gameplay_theme_phase(
        &self,
        vm: &mut Vm,
        scene: ActorScene,
        phase: Phase,
    ) -> Result<bool, Error> {
        if self.root(scene).is_none() {
            return Ok(false);
        }
        let function = vm.new_host_function_with_data(
            load,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Load {
                store: self.store.clone(),
                scene: scene.id,
                phase,
            },
        )?;
        vm.call(function, &[])?;
        Ok(true)
    }
}

fn load(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Load>().unwrap().clone();
    match data.phase {
        Phase::Combo => combo(call, &data)?,
        Phase::Transitions => transitions(call, &data)?,
    }
    lifecycle::invalidate_plans(call, &data.store)
}

fn field(call: &mut HostCall<'_>, actor: TableId, name: &str) -> Result<Value, Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        sprites::field(call, actor, name)
    })
}

fn set(call: &mut HostCall<'_>, actor: TableId, name: &str, value: Value) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor), value], |call| {
        let key = call.try_intern(name.as_bytes())?;
        call.raw_table_set(actor, key, value)
    })
}

fn parent(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    owner: TableId,
) -> Result<(), Error> {
    set(call, actor, "__songlua_parent", Value::Table(owner))?;
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        actor.parent = Some(owner);
    }
    Ok(())
}

fn member(call: &mut HostCall<'_>, owner: TableId, name: &str) -> Result<TableId, Error> {
    let value = field(call, owner, name)?;
    table(call, value)
}

// Materialization owns a separate scene, including implicit offline Def owners.
// Transfer all members before Init: a callback may fail or replace a child, but
// the screen must still release every actor registered by this load.
fn own(call: &mut HostCall<'_>, data: &Load, definition: Value) -> Result<TableId, Error> {
    call.with_roots(&[definition], |call| {
        let scene = materialize(
            call,
            &data.store,
            table(call, definition)?,
            Materialization::Construct,
        )?;
        let mut guard = data.store.lock().unwrap();
        let actor = guard.scenes[&scene].root.expect("constructed actor root");
        if scene != data.scene {
            guard.constructor_scenes.remove(&scene);
            let loaded = guard.scenes.remove(&scene).unwrap();
            for actor in loaded.actors {
                if !guard.scenes[&data.scene].actors.contains(&actor) {
                    guard
                        .scenes
                        .get_mut(&data.scene)
                        .unwrap()
                        .actors
                        .push(actor);
                }
                if guard.actors[&actor].scene == scene {
                    guard.actors.get_mut(&actor).unwrap().scene = data.scene;
                }
            }
        }
        Ok(actor)
    })
}

fn owned_lookup(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    let kind = field(call, actor, "__songlua_actor_type")?;
    if kind != Value::Nil && assets::text(call, kind)?.eq_ignore_ascii_case("ActorFrame") {
        set(
            call,
            actor,
            "__songlua_owned_child_lookup",
            Value::Boolean(true),
        )?;
    }
    native_children::with_children(call, actor, owned_lookup)
}

fn combo(call: &mut HostCall<'_>, data: &Load) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let sl = member(call, globals, "SL")?;
    call.with_roots(&[Value::Table(sl)], |call| {
        // Native gameplay constructs explosions for both players, including a
        // disabled player's retained subtree. HideComboExplosions is Lua truthy.
        for index in 1..=crate::LUA_PLAYERS {
            let player = member(
                call,
                globals,
                &format!("__songlua_top_screen_player_{index}"),
            )?;
            let registry = native_children::helper_function(call, b"native_registry")?;
            let children = call.call(registry, &[Value::Table(player)])?[0];
            call.with_roots(&[children], |call| {
                let combo = member(call, table(call, children)?, "Combo")?;
                call.with_roots(&[Value::Table(combo)], |call| {
                    let mods = member(call, sl, &format!("P{index}"))?;
                    let mods = member(call, mods, "ActiveModifiers")?;
                    let kind = field(call, combo, "__songlua_actor_type")?;
                    let hidden = field(call, mods, "HideComboExplosions")?;
                    if kind == Value::Nil
                        || !assets::text(call, kind)?.eq_ignore_ascii_case("ActorFrame")
                        || !matches!(hidden, Value::Nil | Value::Boolean(false))
                    {
                        return Ok(());
                    }
                    let children = call.call(registry, &[Value::Table(combo)])?[0];
                    call.with_roots(&[children], |call| {
                        let children = table(call, children)?;
                        let number = member(call, children, "Number")?;
                        call.with_roots(&[Value::Table(number)], |call| {
                            for (ordinal, name, thousand) in [
                                (1, "OneHundredMilestone", false),
                                (2, "OneThousandMilestone", true),
                            ] {
                                let definition = load_combo(call, thousand)?;
                                let child = own(call, data, definition)?;
                                let name_value = call.try_intern(name.as_bytes())?;
                                set(call, child, "Name", name_value)?;
                                owned_lookup(call, child)?;
                                initialize(call, &data.store, child)?;
                                // Init runs while the milestone has no Combo parent.
                                parent(call, &data.store, child, combo)?;
                                call.raw_table_set(
                                    combo,
                                    Value::Number(ordinal as f64),
                                    Value::Table(child),
                                )?;
                                set(call, children, name, Value::Table(child))?;
                            }
                            call.raw_table_set(combo, Value::Number(3.), Value::Table(number))?;
                            let mut declared = Vec::new();
                            for index in 1.. {
                                match call.raw_table_get(combo, Value::Number(index as f64))? {
                                    Value::Nil => break,
                                    Value::Table(child) => declared.push(child),
                                    _ => {}
                                }
                            }
                            data.store
                                .lock()
                                .unwrap()
                                .actors
                                .get_mut(&combo)
                                .unwrap()
                                .children = declared;
                            Ok(())
                        })
                    })
                })
            })?;
        }
        Ok(())
    })
}

fn load_combo(call: &mut HostCall<'_>, thousand: bool) -> Result<Value, Error> {
    let globals = helper(call, 5)?;
    let environment = source::environment(call, globals, false)?;
    call.with_roots(&[environment], |call| {
        let loader = call.new_host_function(combo_resource, call.captures().to_vec().as_slice())?;
        set(call, table(call, environment)?, "LoadActor", loader)?;
        source::evaluate(
            call,
            if thousand {
                source::THOUSAND
            } else {
                source::HUNDRED
            },
            environment,
            &[],
        )
    })
}

fn combo_resource(call: &mut HostCall<'_>) -> Result<(), Error> {
    let path = assets::text(call, arg(call, 0))?;
    if path == "../Combo 100milestone" {
        let value = load_combo(call, false)?;
        return call.push(value);
    }
    let key = if path == "explosion.png" {
        "Combo 100milestone/explosion.png"
    } else {
        path.strip_prefix(crate::SONG_LUA_THEME_PATH_PREFIX)
            .and_then(|p| p.strip_prefix("G/"))
            .unwrap_or(&path)
    };
    let path = gameplay_bitmaps::load(key).map_err(|error| call.error(error.as_bytes()))?;
    let definition = call.try_new_table()?;
    call.with_roots(&[Value::Table(definition)], |call| {
        let path = call.try_intern(path.as_bytes())?;
        set(call, definition, "Texture", path)?;
        let globals = table(call, helper(call, 5)?)?;
        let def = member(call, globals, "Def")?;
        let function = field(call, def, "Sprite")?;
        call.call_and_return(function, &[Value::Table(definition)])
    })
}

fn transitions(call: &mut HostCall<'_>, data: &Load) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let top = get(call, globals, b"__songlua_top_screen")?;
    let top = table(call, top)?;
    native_children::with_children(call, top, |call, wrapper| {
        let role = get(call, wrapper, b"__songlua_screen_actor_role")?;
        if role == Value::Nil {
            return Ok(());
        }
        let source = match assets::text(call, role)?.as_str() {
            "Toasty" => source::TOASTY,
            "NextSong" => source::NEXT_SONG,
            "Ready" | "Go" | "Failed" => source::BLANK,
            _ => return Ok(()),
        };
        let definition = source::evaluate(call, source, Value::Table(globals), &[])?;
        let child = own(call, data, definition)?;
        set(
            call,
            wrapper,
            "__songlua_transition_child",
            Value::Table(child),
        )?;
        parent(call, &data.store, child, wrapper)?;
        let mut found = false;
        for i in 1..=call.raw_table_len(wrapper)? {
            found |= call.raw_table_get(wrapper, Value::Number(i as f64))? == Value::Table(child);
        }
        if !found {
            call.raw_table_set(
                wrapper,
                Value::Number((call.raw_table_len(wrapper)? + 1) as f64),
                Value::Table(child),
            )?;
            data.store
                .lock()
                .unwrap()
                .actors
                .get_mut(&wrapper)
                .unwrap()
                .children
                .push(child);
        }
        let registry = native_children::helper_function(call, b"native_registry")?;
        let registry = call.call(registry, &[Value::Table(wrapper)])?[0];
        call.with_roots(&[registry], |call| {
            set(call, table(call, registry)?, "", Value::Table(child))
        })?;
        let visible = field(call, wrapper, "visible")?;
        call.call(visible, &[Value::Table(wrapper), Value::Boolean(true)])?;
        owned_lookup(call, wrapper)?;
        initialize(call, &data.store, child)
    })
}

//! Fresh chunks preserve the bundled source's filename, lines and environment.
use super::*;
use deadlib_lua::NativeLoadStatus;

#[derive(Clone, Copy)]
pub(super) struct Source {
    bytes: &'static [u8],
    name: &'static [u8],
}

macro_rules! bundled {
    ($path:literal) => {
        Source {
            bytes: include_bytes!(concat!("../../../../assets/simply-love/", $path)),
            name: concat!("@theme:/", $path).as_bytes(),
        }
    };
}

pub(super) const HUNDRED: Source = bundled!("Graphics/Combo 100milestone/default.lua");
pub(super) const THOUSAND: Source = bundled!("Graphics/Combo 1000milestone/default.lua");
pub(super) const TOASTY: Source = bundled!("BGAnimations/ScreenGameplay toasty.lua");
pub(super) const NEXT_SONG: Source =
    bundled!("BGAnimations/ScreenGameplay next course song/default.lua");
pub(super) const BLANK: Source = Source {
    bytes: b"return Def.Actor{};",
    name: b"@theme:/BGAnimations/_blank.lua",
};

pub(super) fn evaluate(
    call: &mut HostCall<'_>,
    source: Source,
    environment: Value,
    arguments: &[Value],
) -> Result<Value, Error> {
    let mut values = Vec::with_capacity(arguments.len() + 1);
    values.push(environment);
    values.extend_from_slice(arguments);
    call.with_roots(&values, |call| {
        let loader = call.new_host_function_with_data(evaluate_callback, &[], source)?;
        Ok(call.call(loader, &values)?[0])
    })
}

fn evaluate_callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let source = *call.function_data::<Source>().unwrap();
    let mut stack = call.native_stack()?;
    let count = stack.top();
    if stack.load_buffer(source.bytes, Some(source.name))? != NativeLoadStatus::Ok {
        return Err(stack.raise(stack.value(-1).unwrap()));
    }
    stack.push(stack.value(1).unwrap())?;
    stack.set_environment(-2)?;
    for index in 2..=count {
        stack.push(stack.value(index as isize).unwrap())?;
    }
    stack.call(count - 1, Some(1))?;
    stack.finish(1)
}

pub(super) fn environment(
    call: &mut HostCall<'_>,
    globals: Value,
    forward_writes: bool,
) -> Result<Value, Error> {
    let factory =
        call.new_host_function_with_data(environment_callback, &[globals], forward_writes)?;
    Ok(call.call(factory, &[])?[0])
}

fn environment_callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let globals = call.captures()[0];
    let forward = *call.function_data::<bool>().unwrap();
    let mut stack = call.native_stack()?;
    stack.create_table(0, 1)?;
    stack.create_table(0, 2)?;
    stack.push(globals)?;
    stack.set_field(-2, b"__index")?;
    if forward {
        stack.push(globals)?;
        stack.set_field(-2, b"__newindex")?;
    }
    stack.set_metatable(-2)?;
    stack.finish(1)
}

//! Existing theme helpers used by the gameplay screen's constructor and updates.
use super::fields::{array, object, set};
use super::*;

pub(super) fn install(vm: &mut Vm) -> Result<(), Error> {
    for name in [
        "left",
        "center",
        "middle",
        "right",
        "top",
        "bottom",
        "HorizAlign_Left",
        "HorizAlign_Center",
        "HorizAlign_Right",
        "VertAlign_Top",
        "VertAlign_Middle",
        "VertAlign_Bottom",
    ] {
        let value = vm.try_intern(name.as_bytes())?;
        vm.set_global(name.as_bytes(), value)?;
    }
    for (name, callback) in [
        (
            "BackgroundFilterValues",
            filters as deadlib_lua::HostFunction,
        ),
        ("PlayerColor", player_color),
        ("GetCurrentColor", current_color),
        ("DifficultyColor", difficulty_color),
        ("round", round),
    ] {
        let function = vm.new_host_function(callback, &[])?;
        vm.set_global(name.as_bytes(), function)?;
    }
    let month = crate::song_lua_local_date_globals().month_of_year;
    let function = vm.new_host_function(super::constant, &[Value::Number(month as f64)])?;
    vm.set_global(b"MonthOfYear", function)?;
    for (name, source, chunk) in [
        (
            "IsRoutine",
            include_bytes!("is_routine.lua").as_slice(),
            "@theme:/Scripts/02 Utilities.lua:IsRoutine",
        ),
        (
            "IsSpooky",
            include_bytes!("is_spooky.lua").as_slice(),
            "@theme:/Scripts/SL-Helpers.lua:IsSpooky",
        ),
    ] {
        let code = deadlib_lua::compile_named(source, chunk.as_bytes())?;
        let function = vm.execute(&code)?[0];
        vm.set_global(name.as_bytes(), function)?;
    }
    Ok(())
}

fn arg(call: &HostCall<'_>, index: usize) -> Value {
    call.arguments().get(index).copied().unwrap_or(Value::Nil)
}

fn boolish(call: &HostCall<'_>, value: Value) -> bool {
    match value {
        Value::Boolean(value) => value,
        Value::Number(value) => value != 0.,
        Value::String(_) => super::catalog::text(call, value).is_some_and(|value| {
            let value = value.trim();
            if ["true", "yes", "on"]
                .iter()
                .any(|s| value.eq_ignore_ascii_case(s))
            {
                true
            } else if ["false", "no", "off"]
                .iter()
                .any(|s| value.eq_ignore_ascii_case(s))
            {
                false
            } else {
                value.parse::<f32>().is_ok_and(|value| value != 0.)
            }
        }),
        _ => false,
    }
}

fn filters(call: &mut HostCall<'_>) -> Result<(), Error> {
    let values = object(call, |call, values| {
        for (name, value) in [("Off", 0), ("Dark", 50), ("Darker", 75), ("Darkest", 95)] {
            set(values, name, value, call)?;
        }
        for value in 0..=100 {
            set(values, value, value, call)?;
        }
        Ok(())
    })?;
    call.push(Value::Table(values))
}

fn player_color(call: &mut HostCall<'_>) -> Result<(), Error> {
    let color = super::game_state::player(call, arg(call, 0))
        .map(|player| crate::song_lua_player_color(player, boolish(call, arg(call, 1))))
        .unwrap_or([1.; 4]);
    let color = array(call, color)?;
    call.push(Value::Table(color))
}

fn difficulty_color(call: &mut HostCall<'_>) -> Result<(), Error> {
    let difficulty = match arg(call, 0) {
        Value::Number(value) if value.is_finite() => Some(value.trunc() as i64),
        value @ Value::String(_) => super::catalog::text(call, value)
            .and_then(|value| crate::song_lua_difficulty_index(&value)),
        _ => None,
    };
    let color = difficulty
        .map(|difficulty| crate::song_lua_difficulty_color(difficulty, boolish(call, arg(call, 1))))
        .unwrap_or_else(|| crate::parse_color_text("#B4B7BA").unwrap());
    let color = array(call, color)?;
    call.push(Value::Table(color))
}

fn round(call: &mut HostCall<'_>) -> Result<(), Error> {
    let value = super::catalog::float(call, arg(call, 0)).unwrap_or(0.);
    let precision = super::catalog::float(call, arg(call, 1)).unwrap_or(0.);
    let factor = 10.0_f32.powf(precision.max(0.));
    call.push(Value::Number(((value * factor).round() / factor) as f64))
}

fn current_color(call: &mut HostCall<'_>) -> Result<(), Error> {
    let color = crate::theme_colors::palette_color(
        crate::theme_colors::SONG_LUA_ACTIVE_COLOR_INDEX,
        crate::theme_colors::song_lua_palette(None, boolish(call, arg(call, 0))),
    );
    let color = array(call, color)?;
    call.push(Value::Table(color))
}

//! Legacy lifecycle controls for differential integration tests.
//! Kept behind `test-support` so the tests exercise the actual compiled library
//! without copying its private live-mode or reset implementation.

pub use super::managers::screen::expose_publish as expose_screen_publication;
pub fn begin_legacy_screen_request_capture(lua: &mlua::Lua) {
    if lua.app_data_ref::<crate::live::SourceRequests>().is_none() {
        lua.set_app_data(crate::live::SourceRequests(Vec::new()));
    }
}
pub fn take_legacy_screen_requests(
    lua: &mlua::Lua,
