) -> mlua::Result<Table> {
    let meter = crate::lua_util::create_life_meter_table(
        lua,
        if index == 0 { "LifeP1" } else { "LifeP2" },
        create_default_dummy_actor,
    )?;
    let player = crate::lua_util::create_top_screen_player_actor(
        lua,
        context.players[index].clone(),
